/**
 * Partially updates a task (JSON Merge Patch): absent fields are left unchanged.
 *
 *     Shares the rules and 422 responses of the full update: `TASK_REOPEN_PAST_DAY_NOT_ALLOWED`
 * (completion day, or linked day when `completedAt` is null, before the user's today; tasks with neither are
 * exempt; `details.assignedDate` holds that day) and `TASK_PLAN_COMPLETED_NOT_ALLOWED`
 * (`journalDate` differs from the link of a task that has a `completedAt`),
 * `TASK_PLAN_HAS_OPEN_SUBTASKS` (a task with an open subtask cannot be planned onto a `journalDate` that
 * differs from its current link), plus the parent, block,
 * start and past-day planning codes, and `TASK_PARENT_STATUS_DERIVED` (a parent with an open subtask cannot
 * have its status changed directly; re-sending the stored status is accepted), and
 * `TASK_PARENT_COMPLETED_NOT_ALLOWED` (a task whose resulting status is not Completed cannot be moved under a
 * Completed parent, and a Completed task cannot be reopened while its resulting direct parent is Completed;
 * completing it in the same request, or an open task re-sending its current parent, is accepted), and
 * `TASK_GOAL_NOT_NOW` (a task in a Next or Parked goal cannot be started or completed while the project has a
 * Now goal). `status=todo` on a Blocked task is not refused by that rule: it unblocks to Todo, not InProgress,
 * when the rule forbids InProgress.
 * projectId and goalId change the task's project and goal in the same request, all or nothing: a
 * refusal at any step saves nothing (fields, project, goal, subtasks' goals, planning and events alike), and
 * the same-value project or goal is a no-op. Refusals run in this order: 422 TASK_PROJECT_NOT_FOUND;
 * then, for a goalId, 404 (goal not found), 400 (the task is a subtask: its goal follows its parent,
 * even for the value it would inherit), 400 (the goal is not in the task's resulting project) and 400 (the goal
 * is Done or Dropped); and last 422 TASK_GOAL_NOT_NOW, judged on the resulting goal and status. A project
 * change without a goalId resets the goal (inherited from the parent when the parent's goal is in the new
 * project, otherwise none) and clears the subtasks' goals.
 */
export const patchApiV1TaskItemsById = <ThrowOnError extends boolean = false>(options: Options<PatchApiV1TaskItemsByIdData, ThrowOnError>): RequestResult<PatchApiV1TaskItemsByIdResponses, PatchApiV1TaskItemsByIdErrors, ThrowOnError> => (options.client ?? client).patch<PatchApiV1TaskItemsByIdResponses, PatchApiV1TaskItemsByIdErrors, ThrowOnError>({
    url: '/api/v1/TaskItems/{id}',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Updates a task (full update).
 *
 *     Returns 422 with a body of `{ code, message, details }` for these business rules:
 * * TASK_REOPEN_PAST_DAY_NOT_ALLOWED: a Completed task cannot be reopened once its completion day is
 * before the user's today. The completion day is the local day of the stored completedAt (derived with
 * timezoneOffsetMinutes, UTC when absent), or the linked journal day when completedAt is null
 * (legacy rows). Tasks with neither are exempt. details.assignedDate holds that day. The task stays completed.
 * * TASK_PLAN_COMPLETED_NOT_ALLOWED: a task with a stored completedAt cannot be planned onto a
 * journalDate that differs from its current link. Re-sending the current link, or omitting
 * journalDate, is accepted. Nothing is changed. A request that reopens and re-plans in one call is rejected;
 * reopen first, plan second.
 * * TASK_PARENT_STATUS_DERIVED: a parent with at least one open (not Completed) subtask cannot have its
 * status changed directly, including blocking and unblocking. Re-sending the stored status is accepted.
 * TASK_PARENT_COMPLETE_BLOCKED_BY_CHILDREN takes precedence when completing. Nothing is saved.
 * * TASK_PARENT_COMPLETED_NOT_ALLOWED: a task whose resulting status is not Completed cannot be moved
 * under a Completed parent, and a Completed task cannot be reopened while its resulting direct parent is
 * Completed (reopening and detaching or re-parenting in the same request is judged on the new parent).
 * Completing the task in the same request is accepted, an open task re-sending its current
 * parentTaskItemId with a status that stays open is accepted, and a Completed task stays Completed.
 * Nothing is saved.
 * * TASK_PLAN_HAS_OPEN_SUBTASKS: a task with at least one open (not Completed) subtask cannot be planned
 * onto a journalDate that differs from its current link; plan its subtasks instead. Checked after the
 * Completed-task and past-day rules. details holds taskItemId and journalDate. Nothing is saved.
 * * Other codes: TASK_PARENT_SELF_NOT_ALLOWED, TASK_PARENT_NOT_FOUND,
 * TASK_PARENT_DEPTH_NOT_ALLOWED, TASK_PARENT_COMPLETE_BLOCKED_BY_CHILDREN,
 * TASK_BLOCK_DRAFT_NOT_ALLOWED, TASK_BLOCK_COMPLETED_NOT_ALLOWED,
 * TASK_BLOCKED_REASON_REQUIRES_BLOCKED_STATUS, TASK_START_NOT_ALLOWED,
 * TASK_CREATION_PAST_DAY_NOT_ALLOWED.
 * * TASK_GOAL_NOT_NOW: while the project has a Now goal, a task whose resulting goal is Next or Parked
 * cannot be changed to InProgress or Completed, and cannot take that goal from a new parent while InProgress.
 * Re-sending the stored status is accepted. Checked after the other rules. details holds
 * taskItemId, goalId, nowGoalId and nowGoalTitle. Nothing is saved. Exception:
 * status=todo on a Blocked task is not refused; it unblocks to Todo, not InProgress, when this rule forbids
 * InProgress.
 */
export const putApiV1TaskItemsById = <ThrowOnError extends boolean = false>(options: Options<PutApiV1TaskItemsByIdData, ThrowOnError>): RequestResult<PutApiV1TaskItemsByIdResponses, PutApiV1TaskItemsByIdErrors, ThrowOnError> => (options.client ?? client).put<PutApiV1TaskItemsByIdResponses, PutApiV1TaskItemsByIdErrors, ThrowOnError>({
    url: '/api/v1/TaskItems/{id}',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

